import 'package:flutter/material.dart'; import '../../core/app_state.dart'; import '../../core/models.dart'; import '../../widgets/common.dart'; import '../capture/quick_capture.dart';
class HomePage extends StatelessWidget{const HomePage({super.key});@override Widget build(BuildContext context){final s=AppStateScope.of(context);final today=s.tasks.where((e)=>e.bucket==TaskBucket.today&&!e.completed).toList();final goal=s.goals.isEmpty?null:s.goals.first;return Scaffold(appBar:AppBar(title:const Text('Neru Memory',style:TextStyle(fontWeight:FontWeight.w800)),actions:[IconButton(onPressed:(){showSearch(context:context,delegate:MemorySearch(s));},icon:const Icon(Icons.search))]),body:PageWrap(child:ListView(padding:const EdgeInsets.fromLTRB(18,4,18,100),children:[Text('${DateTime.now().month}月${DateTime.now().day}日',style:Theme.of(context).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.w700)),const SizedBox(height:14),InkWell(borderRadius:BorderRadius.circular(14),onTap:()=>showQuickCapture(context),child:const IgnorePointer(child:TextField(decoration:InputDecoration(prefixIcon:Icon(Icons.add),hintText:'何か覚えておく…')))),const SectionTitle('TODAY'),Card(child:Column(children:[const ListTile(leading:Icon(Icons.calendar_today_outlined),title:Text('Google Calendar'),subtitle:Text('接続後、今日の予定をここに表示します')),for(final t in today)CheckboxListTile(value:t.completed,onChanged:(_)=>s.toggleTask(t),title:Text(t.title),controlAffinity:ListTileControlAffinity.leading)])),const SectionTitle('NEXT'),Card(child:Column(children:[for(final f in s.futures.take(3))ListTile(leading:const Icon(Icons.push_pin_outlined),title:Text(f.title),trailing:Text(f.timing))])),const SectionTitle('GOALS'),if(goal!=null)Card(child:Padding(padding:const EdgeInsets.all(18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Expanded(child:Text(goal.title,style:const TextStyle(fontWeight:FontWeight.w700))),Text('${(goal.progress*100).round()}%')]),const SizedBox(height:10),LinearProgressIndicator(value:goal.progress,borderRadius:BorderRadius.circular(8)),const SizedBox(height:14),Text('NEXT ACTION',style:Theme.of(context).textTheme.labelSmall),const SizedBox(height:4),Text(goal.nextAction)]))),const SectionTitle('REMEMBER'),if(s.wants.isNotEmpty)Card(child:ListTile(leading:const Icon(Icons.lightbulb_outline),title:Text(s.wants.first.title),subtitle:Text(s.wants.first.waitingFor.isEmpty?'しばらく見ていません':s.wants.first.waitingFor),trailing:const Icon(Icons.chevron_right)))])));}}
class MemorySearch extends SearchDelegate<String>{MemorySearch(this.s);final AppState s;@override List<Widget> buildActions(BuildContext c)=>[IconButton(onPressed:()=>query='',icon:const Icon(Icons.clear))];@override Widget buildLeading(BuildContext c)=>IconButton(onPressed:()=>close(c,''),icon:const Icon(Icons.arrow_back));@override Widget buildResults(BuildContext c)=>_body();@override Widget buildSuggestions(BuildContext c)=>_body();Widget _body(){final q=query.toLowerCase();final items=<String>[];items.addAll(s.tasks.where((x)=>x.title.toLowerCase().contains(q)).map((x)=>'Task  ·  ${x.title}'));items.addAll(s.wants.where((x)=>x.title.toLowerCase().contains(q)).map((x)=>'Want  ·  ${x.title}'));items.addAll(s.futures.where((x)=>x.title.toLowerCase().contains(q)).map((x)=>'Future  ·  ${x.title}'));items.addAll(s.goals.where((x)=>x.title.toLowerCase().contains(q)).map((x)=>'Goal  ·  ${x.title}'));return ListView(children:[for(final x in items)ListTile(title:Text(x))]);}}
